//! 🧪️ Real clock producer replies remain bound to their original Source.
use super::*;
use semio_framework_value_control_contract::{OriginalSourceTurn,OriginalSourceTurnIssuer,OriginalSourceTurnIssuerIdentity};
use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
struct ClockWork{issuer:OriginalSourceTurnIssuerIdentity,turn:OriginalSourceTurnIdentity}
impl semio_framework_value_control_contract::OriginalWorkRecipient for ClockWork{
 type Context<'a,'b>=OriginalSystemClockContext<'a> where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if !c.matches_issuer(self.issuer)||c.source_turn()!=self.turn{return Err(invalid())}Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.source_turn())}
 fn admits<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:semio_framework_value_control_contract::OriginalWorkQuote<'r>,_:u64,_:u64)->semio_framework_value_control_contract::OriginalWorkQuoteComplete<'r> where 'b:'a{q.complete(Ok(true))}
 fn settle_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,c:semio_framework_value_control_contract::OriginalWorkPartialCheck<'r>)->semio_framework_value_control_contract::OriginalWorkPartialCheckComplete<'r> where 'b:'a{c.complete(Ok(()))}
 fn recover_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,c:semio_framework_value_control_contract::OriginalWorkPartialCheck<'r>)->semio_framework_value_control_contract::OriginalWorkPartialCheckComplete<'r> where 'b:'a{c.pending()}
}
fn with_clock_work<T>(issuer:&OriginalSourceTurnIssuer,turn:&OriginalSourceTurn,run:impl FnOnce(&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->T)->T{use semio_framework_value_control_contract::{OriginalWork,OriginalWorkAuthority,RetainedAllocationEffect,RetainedCloneGrant};let mut authority=OriginalWorkAuthority::new(ClockWork{issuer:issuer.identity(),turn:turn.identity()});let mut context=OriginalSystemClockContext::new(issuer,turn).unwrap();authority.with_loan(&mut context,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let(mut action,mut receipt,mut actual)=(None,None,None);assert_eq!(work.prepare_for_action(1000,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let grant=RetainedCloneGrant{maximum_items:100,maximum_copy_bytes:100000,maximum_capacity_bytes:100000,maximum_release_bytes:100000,maximum_depth:100};let result={let mut effect=RetainedAllocationEffect::new(grant,1000,&mut actual,receipt.as_mut().unwrap());run(&mut effect)};work.claim_performed_for_action(action,&mut receipt).unwrap();if work.performed_seen_for_action(action).unwrap(){let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());let total=partial.take().unwrap().total();let mut proof=None;assert!(work.commit_for_action(total,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}else{work.cancel_for_action(&mut action).unwrap()}result}).unwrap()}
struct Interrupted{issuer:OriginalSourceTurnIssuerIdentity,calls:Arc<AtomicUsize>,recoveries:Arc<AtomicUsize>}
impl OriginalClockProducer for Interrupted{
 type Context<'a,'b>=OriginalSystemClockContext<'a> where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.issuer.identity()!=self.issuer{return Err(invalid())}c.issuer.validate(c.turn)?;Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.turn.identity())}
  fn demand<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<OriginalClockDemand,ValueError> where 'b:'a{self.validate_context(c)?;Ok(OriginalClockDemand{physical:Default::default(),work:1,next_work:1})}
 fn read<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{if !effect.performed(1)?{return Err(invalid())}self.calls.fetch_add(1,Ordering::Relaxed);let _reply=reply.complete(Ok(Some(99)));panic!("actual clock producer after recording")}
 fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{self.recoveries.fetch_add(1,Ordering::Relaxed);Ok(reply.pending())}
}
#[test]
fn recorded_clock_reply_survives_producer_and_wrapper_unwind(){
 let cases:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/⏱️recorded/cases.json")).unwrap();let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();with_clock_work(&issuer,&turn,|effect|{let foreign_issuer=OriginalSourceTurnIssuer::new();let foreign=foreign_issuer.issue().unwrap();let calls=Arc::new(AtomicUsize::new(0));let recoveries=Arc::new(AtomicUsize::new(0));let mut owner=OriginalClockAuthority::new(Interrupted{issuer:issuer.identity(),calls:calls.clone(),recoveries:recoveries.clone()});let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut wrong=OriginalSystemClockContext::new(&foreign_issuer,&foreign).unwrap();let mut action=None;let mut reading=None;
 {let grant=effect.grant();let mut denied=effect.reborrow(grant,0).unwrap();assert!(!owner.drive(&mut context,&mut denied,&mut action).unwrap());assert!(action.is_none());assert_eq!(calls.load(Ordering::Relaxed),0)}let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||owner.drive(&mut context,effect,&mut action).unwrap()));assert!(interrupted.is_err());assert!(owner.has_pending_action());assert!(owner.drive(&mut wrong,effect,&mut action).is_err());with_clock_work(&issuer,&turn,|other_work|{assert!(owner.drive(&mut context,other_work,&mut action).is_err())});assert!(owner.drive(&mut context,effect,&mut action).unwrap());let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{assert!(action.as_mut().unwrap().transfer_reading(&mut reading).unwrap());panic!("wrapper after resident clock reading")}));assert!(interrupted.is_err());let observation=*reading.as_ref().unwrap().as_ref().unwrap();assert_eq!(observation.reading(),Some(99));assert!(observation.monotonic());let deadline=owner.deadline_from(&context,observation,1).unwrap();assert!(!owner.should_yield(&context,deadline,observation,5).unwrap());assert_eq!(cases[2]["yield"],false);assert!(owner.finish(&wrong,&mut action).is_err());assert!(owner.has_pending_action());owner.finish(&context,&mut action).unwrap();assert_eq!(calls.load(Ordering::Relaxed),1);assert_eq!(recoveries.load(Ordering::Relaxed),0);assert!(owner.into_producer().is_ok())});
}
#[test]
fn system_clock_reads_its_actual_source_and_rejects_a_foreign_issuer(){
 let issuer=OriginalSourceTurnIssuer::new();let turn:OriginalSourceTurn=issuer.issue().unwrap();with_clock_work(&issuer,&turn,|effect|{let alien=OriginalSourceTurnIssuer::new();let wrong=alien.issue().unwrap();let mut authority=OriginalClockAuthority::new(OriginalSystemClock::new(&issuer));assert!(authority.inspect(|clock|clock.origin.is_none()));let mut actual=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut foreign=OriginalSystemClockContext::new(&alien,&wrong).unwrap();let mut action=None;let mut reading=None;assert!(authority.drive(&mut foreign,effect,&mut action).is_err());assert!(action.is_none());assert!(authority.inspect(|clock|clock.origin.is_none()));assert!(authority.drive(&mut actual,effect,&mut action).unwrap());assert!(authority.inspect(|clock|clock.origin.is_some()));assert!(action.as_mut().unwrap().transfer_reading(&mut reading).unwrap());let observation=reading.take().unwrap().unwrap();assert!(observation.reading().is_some()&&observation.monotonic());let deadline=authority.deadline_from(&actual,observation,10_000).unwrap();authority.finish(&actual,&mut action).unwrap();let mut other=OriginalClockAuthority::new(OriginalSystemClock::new(&issuer));let mut denied=OriginalClockDecisionFrame::new();assert_eq!(denied.poll(&mut other,&mut actual,effect,deadline,1).unwrap(),OriginalClockDecisionStatus::Refused);assert!(!other.has_pending_action());assert!(other.inspect(|clock|clock.origin.is_none()));let mut refusal=None;assert!(denied.transfer_refusal(&mut refusal).unwrap());drop(refusal);denied.cancel_unstarted().unwrap();let mut other_action=None;assert!(other.drive(&mut actual,effect,&mut other_action).unwrap());let mut other_reading=None;assert!(other_action.as_mut().unwrap().transfer_reading(&mut other_reading).unwrap());let other_observation=other_reading.take().unwrap().unwrap();assert!(other.should_yield(&actual,deadline,other_observation,1).is_err());other.finish(&actual,&mut other_action).unwrap();assert!(other.into_producer().is_ok());assert!(authority.into_producer().is_ok())});
}

#[test]
fn recorded_clock_preserves_a_real_backward_reading_and_refuses_deadline_admission(){
 struct Scripted{issuer:OriginalSourceTurnIssuerIdentity,read:usize}
 impl OriginalClockProducer for Scripted{
  type Context<'a,'b>=OriginalSystemClockContext<'a> where 'b:'a;
  fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.issuer.identity()!=self.issuer{return Err(invalid())}c.issuer.validate(c.turn)?;Ok(())}
  fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.turn.identity())}
  fn demand<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<OriginalClockDemand,ValueError> where 'b:'a{self.validate_context(c)?;Ok(OriginalClockDemand{physical:Default::default(),work:1,next_work:1})}
  fn read<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{if !effect.performed(1)?{return Err(invalid())}let reading=[1u128<<64,(1u128<<64)-1][self.read];self.read+=1;Ok(reply.complete(Ok(Some(reading))))}
  fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{Ok(reply.pending())}
 }
 let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();with_clock_work(&issuer,&turn,|effect|{let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut owner=OriginalClockAuthority::new(Scripted{issuer:issuer.identity(),read:0});let mut action=None;let mut deadline=None;let mut first_observation=None;for (expected,monotonic) in [(1u128<<64,true),((1u128<<64)-1,false)]{assert!(owner.drive(&mut context,effect,&mut action).unwrap());let mut output=None;assert!(action.as_mut().unwrap().transfer_reading(&mut output).unwrap());let observed=output.take().unwrap().unwrap();assert_eq!((observed.reading(),observed.monotonic()),(Some(expected),monotonic));if monotonic{deadline=Some(owner.deadline_from(&context,observed,100).unwrap());first_observation=Some(observed)}else{assert!(owner.should_yield(&context,deadline.unwrap(),first_observation.unwrap(),1).is_err());assert!(owner.should_yield(&context,deadline.unwrap(),observed,1).unwrap())}owner.finish(&context,&mut action).unwrap();if monotonic{let mut zero=OriginalClockDecisionFrame::new();assert_eq!(zero.poll(&mut owner,&mut context,effect,deadline.unwrap(),0).unwrap(),OriginalClockDecisionStatus::Ready);let mut output=None;assert!(zero.transfer_decision(0,&mut output).unwrap());assert_eq!(output,Some(true));zero.finish(&mut owner,&context).unwrap();assert_eq!(owner.inspect(|producer|producer.read),1)}}assert_eq!(owner.into_producer().ok().unwrap().read,2)});
}

#[test]
fn clock_retains_a_recorded_reading_and_an_independent_original_refusal(){
 struct Both{issuer:OriginalSourceTurnIssuerIdentity,error:Option<ValueError>,calls:usize}
 impl OriginalClockProducer for Both{
  type Context<'a,'b>=OriginalSystemClockContext<'a> where 'b:'a;
  fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.issuer.identity()!=self.issuer{return Err(invalid())}c.issuer.validate(c.turn)?;Ok(())}
  fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.turn.identity())}
  fn demand<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<OriginalClockDemand,ValueError> where 'b:'a{self.validate_context(c)?;Ok(OriginalClockDemand{physical:Default::default(),work:1,next_work:1})}
  fn read<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{if !effect.performed(1)?{return Err(invalid())}self.calls+=1;let _reply=reply.complete(Ok(Some(42)));Err(self.error.take().unwrap())}
  fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{Ok(reply.pending())}
 }
 let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();with_clock_work(&issuer,&turn,|effect|{let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let error=ValueError::new(ValueRefusalKind::Canceled,"actual clock source refusal".to_owned());let pointer=error.message.as_ptr();let mut owner=OriginalClockAuthority::new(Both{issuer:issuer.identity(),error:Some(error),calls:0});let(mut action,mut refusal,mut reading)=(None,None,None);assert!(!owner.drive(&mut context,effect,&mut action).unwrap());assert!(action.as_mut().unwrap().transfer_refusal(&mut refusal).unwrap());assert_eq!(refusal.as_ref().unwrap().message.as_ptr(),pointer);assert!(owner.drive(&mut context,effect,&mut action).unwrap());assert!(action.as_mut().unwrap().transfer_reading(&mut reading).unwrap());assert_eq!(reading.take().unwrap().unwrap().reading(),Some(42));owner.finish(&context,&mut action).unwrap();assert_eq!(owner.into_producer().ok().unwrap().calls,1)});
}

#[test]
fn resident_deadline_decision_recovers_the_same_original_clock_reply(){
 let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();with_clock_work(&issuer,&turn,|effect|{let calls=Arc::new(AtomicUsize::new(0));let recoveries=Arc::new(AtomicUsize::new(0));let mut owner=OriginalClockAuthority::new(Interrupted{issuer:issuer.identity(),calls:calls.clone(),recoveries:recoveries.clone()});let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut initial=None;assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||owner.drive(&mut context,effect,&mut initial).unwrap())).is_err());assert!(owner.drive(&mut context,effect,&mut initial).unwrap());let mut observation=None;assert!(initial.as_mut().unwrap().transfer_reading(&mut observation).unwrap());let deadline=owner.deadline_from(&context,observation.take().unwrap().unwrap(),1).unwrap();owner.finish(&context,&mut initial).unwrap();let mut frame=OriginalClockDecisionFrame::new();let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||frame.poll(&mut owner,&mut context,effect,deadline,5).unwrap()));assert!(interrupted.is_err());assert!(!frame.terminal_is_empty());assert_eq!(frame.poll(&mut owner,&mut context,effect,deadline,5).unwrap(),OriginalClockDecisionStatus::Ready);let mut output=None;assert!(frame.transfer_decision(5,&mut output).unwrap());assert_eq!(output,Some(false));frame.finish(&mut owner,&context).unwrap();assert!(frame.terminal_is_empty());assert_eq!(calls.load(Ordering::Relaxed),2);assert_eq!(recoveries.load(Ordering::Relaxed),0);assert!(owner.into_producer().is_ok())});
}

#[test]
fn owned_host_clock_recovers_the_actual_recorded_reply(){
 struct Host{calls:usize,recoveries:usize}
 impl OriginalHostClockProducer for Host{fn demand(&self,_:&OriginalSystemClockContext<'_>)->Result<OriginalClockDemand,ValueError>{Ok(OriginalClockDemand{physical:Default::default(),work:1,next_work:1})}
  fn read<'reply>(&mut self,_:&OriginalSystemClockContext<'_>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,reply:OriginalClockReply<'reply>)->Result<OriginalClockReplyComplete<'reply>,ValueError>{if !effect.performed(1)?{return Err(invalid())}self.calls+=1;let _reply=reply.complete(Ok(Some(77)));panic!("host after recorded reading")}
  fn recover<'reply>(&mut self,_:&OriginalSystemClockContext<'_>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,reply:OriginalClockReply<'reply>)->Result<OriginalClockReplyComplete<'reply>,ValueError>{self.recoveries+=1;Ok(reply.pending())}
 }
 let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();with_clock_work(&issuer,&turn,|effect|{let foreign=OriginalSourceTurnIssuer::new();let other=foreign.issue().unwrap();let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut wrong=OriginalSystemClockContext::new(&foreign,&other).unwrap();let mut clock=OriginalClockAuthority::new(OriginalHostClock::new(&issuer,Host{calls:0,recoveries:0}));let mut action=None;assert!(clock.drive(&mut wrong,effect,&mut action).is_err());assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||clock.drive(&mut context,effect,&mut action).unwrap())).is_err());assert!(clock.drive(&mut context,effect,&mut action).unwrap());let mut reading=None;assert!(action.as_mut().unwrap().transfer_reading(&mut reading).unwrap());assert_eq!(reading.unwrap().unwrap().reading(),Some(77));clock.finish(&context,&mut action).unwrap();let host=clock.into_producer().ok().unwrap().into_host();assert_eq!((host.calls,host.recoveries),(1,0));});
}

#[test]
fn erased_host_admission_denial_keeps_the_actual_source_owner(){
 struct Host(u8);
 impl OriginalHostClockProducer for Host{
  fn demand(&self,_:&OriginalSystemClockContext<'_>)->Result<OriginalClockDemand,ValueError>{Ok(OriginalClockDemand{physical:Default::default(),work:1,next_work:1})}
  fn read<'r>(&mut self,_:&OriginalSystemClockContext<'_>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,r:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError>{if !effect.performed(1)?{return Err(invalid())}let _reply=r.complete(Ok(Some(u128::from(self.0))));panic!("Source host unwound after its actual reply")}
  fn recover<'r>(&mut self,_:&OriginalSystemClockContext<'_>,_:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,r:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError>{Ok(r.pending())}
 }
 impl semio_framework_value_retirement::retirement::RetireOwned for Host{type RetirementCursor=semio_framework_value_retirement::retirement::Leaf<u8>;fn retirement_seed(self)->Self::RetirementCursor{semio_framework_value_retirement::retirement::leaf(self.0)}fn retirement_birth_bytes(&self)->Option<usize>{Some(semio_framework_value_retirement::retirement::leaf_birth_bytes::<u8>())}fn controlled_retirement_supported()->bool{true}}
 let cases:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/⏱️recorded/host-admission.json")).unwrap();assert_eq!(cases[0]["items"],0);assert_eq!(cases[0]["admitted"],false);let issuer=OriginalSourceTurnIssuer::new();let dispatch=issuer.issue().unwrap();with_clock_work(&issuer,&dispatch,|effect|{let mut host=Some(OriginalClockAuthority::new(OriginalHostClock::new(&issuer,Host(77))));let mut source=OriginalSourceClock::new();let mut context=OriginalSystemClockContext::new(&issuer,&dispatch).unwrap();{let remaining=effect.remaining_work_units().unwrap();let mut denied=effect.reborrow(Default::default(),remaining).unwrap();let turn=source.admit(&context,&mut host,&mut denied);assert!(turn.result.unwrap().is_none());assert_eq!(turn.work,0)}assert!(effect.actual().is_none()&&source.terminal_is_empty());let turn=source.admit(&context,&mut host,effect);let born=turn.result.unwrap().unwrap();assert!(host.is_none());assert_eq!(*effect.actual(),Some(born.retained_capacity_bytes));*effect.actual()=None;assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||source.poll_reading(&mut context,effect,1000).unwrap())).is_err());with_clock_work(&issuer,&dispatch,|other_work|{assert_eq!(source.poll_reading(&mut context,other_work,1000).unwrap(),OriginalClockDecisionStatus::Refused)});let mut wrong_work_refusal=None;assert!(source.take_refusal(&context,&mut wrong_work_refusal).unwrap());assert_eq!(source.poll_reading(&mut context,effect,1000).unwrap(),OriginalClockDecisionStatus::Ready);let mut reading=None;assert!(source.take_reading(&context,&mut reading).unwrap());let observation=reading.unwrap().unwrap();assert_eq!(observation.reading(),Some(77));let deadline=source.deadline(&context,observation,1).unwrap();assert!(source.deadline(&context,observation,2).is_err());source.finish_reading(&context).unwrap();assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||source.poll_decision(&mut context,effect,deadline,1000).unwrap())).is_err());assert_eq!(source.poll_decision(&mut context,effect,deadline,999).unwrap(),OriginalClockDecisionStatus::Ready);assert!(source.allows(&context,998).unwrap());assert!(!source.allows(&context,0).unwrap());assert!(source.allows(&context,1001).is_err());let mut decision=None;assert!(source.take_decision(&context,0,&mut decision).unwrap());assert_eq!(decision,Some(true));source.finish_decision(&context).unwrap();assert!(source.allows(&context,0).is_err());let mut released=0;for _ in 0..100{if source.terminal_is_empty(){break}let poll=semio_framework_value_control_contract::invoke_original(effect,None,|inner|source.retirement_step(inner)).unwrap().unwrap();match poll{semio_framework_value_control_contract::RetainedWorkPoll::Pending{..}=>assert!(effect.actual().is_none()),semio_framework_value_control_contract::RetainedWorkPoll::Complete(turn)=>{let step=turn.result.unwrap();let progress=step.progress();released+=progress.released_bytes;if let Some(actual)=*effect.actual(){assert_eq!(actual,progress.retained_capacity_bytes);*effect.actual()=None}}}}assert!(source.terminal_is_empty());assert!(released>=born.retained_capacity_bytes);assert!(host.is_none())});
}

#[test]
fn pending_clock_recovers_using_only_remaining_original_work(){
 struct Host{reads:u8,recoveries:u8}
 impl OriginalHostClockProducer for Host{
  fn demand(&self,_:&OriginalSystemClockContext<'_>)->Result<OriginalClockDemand,ValueError>{Ok(OriginalClockDemand{physical:Default::default(),work:2,next_work:1})}
  fn read<'r>(&mut self,_:&OriginalSystemClockContext<'_>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError>{if !effect.performed(1)?{return Err(invalid())}self.reads+=1;Ok(reply.pending())}
  fn recover<'r>(&mut self,_:&OriginalSystemClockContext<'_>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError>{if !effect.performed(1)?{return Err(invalid())}self.recoveries+=1;Ok(reply.complete(Ok(Some(81))))}
 }
 let cases:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/⏱️recorded/work-demand.json")).unwrap();assert_eq!(cases[4]["admitted"],true);let issuer=OriginalSourceTurnIssuer::new();let dispatch=issuer.issue().unwrap();with_clock_work(&issuer,&dispatch,|parent|{let grant=parent.grant();let mut effect=parent.reborrow(grant,2).unwrap();let mut context=OriginalSystemClockContext::new(&issuer,&dispatch).unwrap();let mut owner=OriginalClockAuthority::new(OriginalHostClock::new(&issuer,Host{reads:0,recoveries:0}));let mut action=None;assert!(!owner.drive(&mut context,&mut effect,&mut action).unwrap());assert_eq!(effect.performed_work(),1);assert!(owner.drive(&mut context,&mut effect,&mut action).unwrap());assert_eq!(effect.performed_work(),2);let mut reading=None;assert!(action.as_mut().unwrap().transfer_reading(&mut reading).unwrap());assert_eq!(reading.unwrap().unwrap().reading(),Some(81));owner.finish(&context,&mut action).unwrap();let host=owner.into_producer().ok().unwrap().into_host();assert_eq!((host.reads,host.recoveries),(1,1))});
}

#[test]
fn clock_work_scope_claims_before_unwind(){
 use semio_framework_value_control_contract::{OriginalWork,OriginalWorkAuthority,OriginalWorkBorrow,RetainedCloneGrant};
 let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let calls=Arc::new(AtomicUsize::new(0));let recoveries=Arc::new(AtomicUsize::new(0));let mut authority=OriginalWorkAuthority::new(ClockWork{issuer:issuer.identity(),turn:turn.identity()});let mut source=OriginalSystemClockContext::new(&issuer,&turn).unwrap();
 authority.with_loan(&mut source,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let mut borrow=OriginalWorkBorrow::new(&mut work);let(mut action,mut receipt,mut claim,mut actual)=(None,None,None,None);assert_eq!(borrow.prepare(1,&mut action).unwrap(),Some(true));let mut clock=OriginalClockAuthority::new(Interrupted{issuer:issuer.identity(),calls:calls.clone(),recoveries:recoveries.clone()});let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut reading_action=None;let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};
 let unwind=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let mut guard=borrow.performed_scope(action,&mut receipt,&mut claim).unwrap();let mut effect=guard.effect(grant,1,&mut actual).unwrap();let _=clock.drive(&mut context,&mut effect,&mut reading_action);}));assert!(unwind.is_err());assert_eq!(claim.take().unwrap().unwrap(),1);assert_eq!(borrow.actual(),1);let mut partial=None;assert!(borrow.settle_partial_into(action,&mut partial).unwrap());assert_eq!(partial.take().unwrap().total(),1);
 {let mut guard=borrow.performed_scope(action,&mut receipt,&mut claim).unwrap();let mut effect=guard.effect(grant,0,&mut actual).unwrap();assert!(clock.drive(&mut context,&mut effect,&mut reading_action).unwrap());}assert_eq!(claim.take().unwrap().unwrap(),1);let mut reading=None;assert!(reading_action.as_mut().unwrap().transfer_reading(&mut reading).unwrap());assert_eq!(reading.unwrap().unwrap().reading(),Some(99));clock.finish(&context,&mut reading_action).unwrap();let mut proof=None;assert!(borrow.commit(1,action,&mut proof).unwrap());borrow.finish(&mut proof,&mut action).unwrap();assert_eq!(calls.load(Ordering::Relaxed),1);assert_eq!(recoveries.load(Ordering::Relaxed),0);drop(clock.into_producer().ok().unwrap());}).unwrap();
}

#[test]
fn decision_recovery_uses_current_same_turn_fuel(){
 let cases:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/⏱️recorded/decision-fuel.json")).unwrap();assert_eq!(cases[1]["shouldYield"],true);let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();with_clock_work(&issuer,&turn,|effect|{let calls=Arc::new(AtomicUsize::new(0));let recoveries=Arc::new(AtomicUsize::new(0));let mut owner=OriginalClockAuthority::new(Interrupted{issuer:issuer.identity(),calls:calls.clone(),recoveries:recoveries.clone()});let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut initial=None;assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||owner.drive(&mut context,effect,&mut initial).unwrap())).is_err());assert!(owner.drive(&mut context,effect,&mut initial).unwrap());let mut observation=None;assert!(initial.as_mut().unwrap().transfer_reading(&mut observation).unwrap());let deadline=owner.deadline_from(&context,observation.take().unwrap().unwrap(),1).unwrap();owner.finish(&context,&mut initial).unwrap();let mut frame=OriginalClockDecisionFrame::new();assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||frame.poll(&mut owner,&mut context,effect,deadline,2).unwrap())).is_err());assert!(frame.poll(&mut owner,&mut context,effect,deadline,3).is_err());assert_eq!(frame.poll(&mut owner,&mut context,effect,deadline,1).unwrap(),OriginalClockDecisionStatus::Ready);let mut decision=None;assert!(frame.transfer_decision(2,&mut decision).is_err());assert!(frame.transfer_decision(0,&mut decision).unwrap());assert_eq!(decision,Some(true));frame.finish(&mut owner,&context).unwrap();assert_eq!(calls.load(Ordering::Relaxed),2);assert_eq!(recoveries.load(Ordering::Relaxed),0);assert!(owner.into_producer().is_ok())});
}

#[test]
fn paid_work_and_construction_authority_birth(){
 use semio_framework_value_control_contract::{OriginalWorkAuthority,OriginalWorkRecipient,OriginalWorkQuote,OriginalWorkQuoteComplete,OriginalWorkPartialCheck,OriginalWorkPartialCheckComplete,OriginalConstructionAuthority,OriginalConstructionRecipient,OriginalConstructionGrant,OriginalConstructionGrantComplete,OriginalConstructionAccept,OriginalConstructionAcceptComplete,RetainedCloneGrant,RetainedCloneProgress};
 struct Work{issuer:OriginalSourceTurnIssuerIdentity,owner:Box<u8>}
 impl OriginalWorkRecipient for Work{type Context<'a,'b>=OriginalSystemClockContext<'a> where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.matches_issuer(self.issuer){Ok(())}else{Err(invalid())}}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.source_turn())}fn admits<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:OriginalWorkQuote<'r>,_:u64,_:u64)->OriginalWorkQuoteComplete<'r> where 'b:'a{q.complete(Ok(true))}fn settle_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,c:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{c.complete(Ok(()))}fn recover_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,c:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{c.pending()}}
 struct Construction{issuer:OriginalSourceTurnIssuerIdentity,owner:Box<u8>}
 impl OriginalConstructionRecipient for Construction{type Context<'a,'b>=OriginalSystemClockContext<'a> where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.matches_issuer(self.issuer){Ok(())}else{Err(invalid())}}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.source_turn())}fn grant<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:OriginalConstructionGrant<'r>)->OriginalConstructionGrantComplete<'r> where 'b:'a{q.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:10000,maximum_capacity_bytes:10000,maximum_release_bytes:10000,maximum_depth:1}))}fn accept<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,r:OriginalConstructionAccept<'r>)->OriginalConstructionAcceptComplete<'r> where 'b:'a{r.complete(Ok(()))}fn submitted<'a,'b>(&self,_:&Self::Context<'a,'b>)->RetainedCloneProgress where 'b:'a{Default::default()}}
 let cases:serde_json::Value=serde_json::from_str(include_str!("../../../../🌱️value/🎟️control/🧬️contract/🎟️work-action/🤝️loan/🧪️tests/authority-birth.json")).unwrap();assert_eq!(cases[0]["admitted"],false);let issuer=OriginalSourceTurnIssuer::new();let dispatch=issuer.issue().unwrap();let foreign=OriginalSourceTurnIssuer::new();let other=foreign.issue().unwrap();let context=OriginalSystemClockContext::new(&issuer,&dispatch).unwrap();let wrong=OriginalSystemClockContext::new(&foreign,&other).unwrap();with_clock_work(&issuer,&dispatch,|effect|{let mut w=Some(Work{issuer:issuer.identity(),owner:Box::new(3)});let mut c=Some(Construction{issuer:issuer.identity(),owner:Box::new(4)});let wp=&*w.as_ref().unwrap().owner as *const u8;let cp=&*c.as_ref().unwrap().owner as *const u8;let(mut wa,mut ca)=(None,None);let grant=effect.grant();{let mut denied=effect.reborrow(grant,0).unwrap();assert!(OriginalWorkAuthority::admit_from(&mut w,&mut wa,&context,&mut denied).result.unwrap().is_none());assert!(OriginalConstructionAuthority::admit_from(&mut c,&mut ca,&context,&mut denied).result.unwrap().is_none())}assert!(OriginalWorkAuthority::admit_from(&mut w,&mut wa,&wrong,effect).result.is_err());assert_eq!(&*w.as_ref().unwrap().owner as *const u8,wp);assert_eq!(&*c.as_ref().unwrap().owner as *const u8,cp);let a=OriginalWorkAuthority::admit_from(&mut w,&mut wa,&context,effect);assert_eq!(a.work,1);assert_eq!(a.result.unwrap().unwrap().copied_bytes,OriginalWorkAuthority::<Work>::birth_demand().unwrap().copy_bytes);let b=OriginalConstructionAuthority::admit_from(&mut c,&mut ca,&context,effect);assert_eq!(b.work,1);assert_eq!(b.result.unwrap().unwrap().copied_bytes,OriginalConstructionAuthority::<Construction>::birth_demand().unwrap().copy_bytes);{let mut denied=effect.reborrow(grant,0).unwrap();assert!(OriginalWorkAuthority::return_into(&mut wa,&mut w,&context,&mut denied).result.unwrap().is_none());assert!(OriginalConstructionAuthority::return_into(&mut ca,&mut c,&context,&mut denied).result.unwrap().is_none())}assert!(OriginalWorkAuthority::return_into(&mut wa,&mut w,&wrong,effect).result.is_err());assert!(w.is_none()&&c.is_none());assert_eq!(OriginalWorkAuthority::return_into(&mut wa,&mut w,&context,effect).work,1);assert_eq!(OriginalConstructionAuthority::return_into(&mut ca,&mut c,&context,effect).work,1);assert!(wa.is_none()&&ca.is_none());assert_eq!(&*w.as_ref().unwrap().owner as *const u8,wp);assert_eq!(&*c.as_ref().unwrap().owner as *const u8,cp)});
}

#[test]
fn monotonic_port_elapsed_matches_the_language_agnostic_cases(){
 use crate::monotonic::MonotonicPort;
 struct Scripted;
 impl MonotonicPort for Scripted{type Mark=u64;fn mark()->Result<u64,ValueError>{Ok(0)}fn elapsed_micros(origin:u64,now:u64)->Option<u128>{now.checked_sub(origin).map(u128::from)}}
 let cases:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/⏱️recorded/monotonic.json")).unwrap();
 for case in cases.as_array().unwrap(){let origin=case["origin"].as_u64().unwrap();let now=case["now"].as_u64().unwrap();assert_eq!(Scripted::elapsed_micros(origin,now),case["elapsedMicros"].as_u64().map(u128::from))}
}

#[cfg(not(all(target_arch="wasm32",target_os="unknown")))]
#[test]
fn selected_monotonic_source_is_ordered_in_microseconds(){
 use crate::monotonic::{MonotonicPort,SelectedMonotonic};
 let origin=SelectedMonotonic::mark().unwrap();let mut previous=0u128;
 for _ in 0..200{let now=SelectedMonotonic::mark().unwrap();let elapsed=SelectedMonotonic::elapsed_micros(origin,now).unwrap();assert!(elapsed>=previous);previous=elapsed}
 std::thread::sleep(std::time::Duration::from_millis(5));
 let later=SelectedMonotonic::mark().unwrap();let elapsed=SelectedMonotonic::elapsed_micros(origin,later).unwrap();
 assert!(elapsed>=5_000&&elapsed<60_000_000,"elapsed {elapsed} is not microseconds");
 assert_eq!(SelectedMonotonic::elapsed_micros(later,origin),None);
}
